import{_ as o}from"./chunks/path-hugo.CBIlszOp.js";import{_ as e,c as d,o as a,ag as s}from"./chunks/framework.3IuuWm4t.js";const m=JSON.parse('{"title":"Hugo 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/github-hugo.md","filePath":"platforms/github-hugo.md","lastUpdated":1795809563000}'),i={name:"platforms/github-hugo.md"};function c(l,t,r,n,g,u){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="hugo-配置指南" tabindex="-1">Hugo 配置指南 <a class="header-anchor" href="#hugo-配置指南" aria-label="Permalink to &quot;Hugo 配置指南&quot;">​</a></h1><p>通过 <strong>GitHub API</strong> 将文章发布到 <strong>Hugo</strong> 静态博客仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Hugo 博客仓库的 <strong>GitHub 仓库</strong>（如 <code>hugo-blog</code>）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitHub Token（PAT）</strong>（GitHub Settings → Developer settings → Personal access tokens，勾选 <code>repo</code> 权限）。</li><li>该仓库是一个标准 Hugo 项目（含 <code>hugo.toml</code>/<code>hugo.yaml</code> 与 <code>content/</code>、<code>static/</code> 目录）。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>首页地址</td><td>GitHub 首页地址，默认 <code>https://github.com</code></td></tr><tr><td>API 地址</td><td>GitHub API 地址，默认 <code>https://api.github.com</code>，通常无需修改</td></tr><tr><td>用户名</td><td>GitHub 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitHub 个人访问令牌（PAT），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>Hugo 博客仓库名，与用户名组成 <code>&lt;user&gt;/&lt;repo&gt;</code>，如 <code>hugo-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code>，需与仓库实际分支一致</td></tr><tr><td>存储目录</td><td>Hugo 文章存储目录，默认 <code>content/post</code>。发布后的 <code>.md</code> 写入该目录（随 section 决定文章 URL）</td></tr><tr><td>内容组织方式</td><td><code>单文件</code>（默认）或 <code>页面目录（Leaf Bundle）</code>；后者把文章写成 <code>&lt;存储目录&gt;/&lt;目录名&gt;/index.md</code>，图片放同目录</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[slug].md</code>；页面目录模式下去掉 <code>.md</code> 后作为文章目录名</td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code>；页面目录模式改为目录式（如 <code>/post/[postid]/</code>）</td></tr><tr><td>预览规则</td><td>GitHub blob 预览规则，默认 <code>/[user]/[repo]/blob/[branch]/[docpath]</code></td></tr><tr><td>图床</td><td>Hugo 支持内置图床，选「当前平台」：图片上传到仓库 <code>static/images</code>（默认），文章中引用为绝对路径 <code>/images/&lt;图片名&gt;</code></td></tr></tbody></table><h2 id="三、图片与目录约定-hugo-官方规范" tabindex="-1">三、图片与目录约定（Hugo 官方规范） <a class="header-anchor" href="#三、图片与目录约定-hugo-官方规范" aria-label="Permalink to &quot;三、图片与目录约定（Hugo 官方规范）&quot;">​</a></h2><ul><li>Hugo 的 <strong><code>static/</code> 目录</strong>构建时会被<strong>原样复制到站点根目录</strong>。放在 <code>static/images/</code> 下的图片，站点根 URL 就是 <code>/images/&lt;图片名&gt;</code>。</li><li>因此在 Markdown 中引用文章图片使用 <strong>绝对路径 <code>/images/&lt;图片名&gt;</code></strong> 即可——构建产物（<code>public/</code>）中该路径能正确解析到图片。这也是社区与官方文档推荐的引用方式。</li><li>文章的最终 URL（permalink）由<strong>所在 section（content 下的目录）+ slug</strong> 决定。默认 <code>[slug].md</code> 文件名 + 开启「YAML 永久链接」时，插件会在 front matter 写入 <code>url</code>，取值<strong>固定为 <code>/post/&lt;slug&gt;.html</code></strong>（不读取「文章预览规则」，只是两者默认恰好一致），保证查看链接可打开；若你改了「文章预览规则」，需自行确认站点实际地址是否仍是 <code>/post/&lt;slug&gt;.html</code>。</li><li>Hugo front matter 中未显式写 <code>draft</code> 时文章默认为<strong>发布</strong>状态（<code>draft</code> 默认 <code>false</code>），构建时会被正常渲染。</li></ul><h2 id="四、页面目录-leaf-bundle-模式" tabindex="-1">四、页面目录（Leaf Bundle）模式 <a class="header-anchor" href="#四、页面目录-leaf-bundle-模式" aria-label="Permalink to &quot;四、页面目录（Leaf Bundle）模式&quot;">​</a></h2><p>在「内容组织方式」选择「页面目录（Leaf Bundle）」时，插件按 Hugo 的 page bundle 约定发布：</p><ul><li>文章写入 <code>content/post/&lt;目录名&gt;/index.md</code>（目录名来自「文件规则」，默认即 slug）。</li><li>图片自动写入 <code>index.md</code> 同目录，正文使用相对文件名（如 <code>cover.jpg</code>），由 Hugo 作为 page resource 发布到同一 URL 目录；不需要再配置「图片存储目录 / 图片访问链接」。</li><li>开启「YAML 永久链接」时，front matter 的 <code>url</code> 使用目录式地址（按存储目录推导，如 <code>content/posts/</code> → <code>/posts/&lt;slug&gt;/</code>）。</li><li>「文章预览规则」通常也要改成目录形式，例如 <code>/post/[postid]/</code> 或 <code>/posts/[postid]/</code>，具体以站点实际地址为准。</li><li>更新会按 <code>index.md</code> 定位；删除文章时会一并清理该文章目录内的图片（子目录中的自定义资源需手动处理）。</li><li>默认仍是单文件模式；切换只影响之后新发布的文章；已发布文章更新时保持原路径与图片方式，不会自动搬迁或改造。</li></ul><h2 id="五、验证与发布" tabindex="-1">五、验证与发布 <a class="header-anchor" href="#五、验证与发布" aria-label="Permalink to &quot;五、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ Token、仓库、分支校验通过（会向仓库发布并清理测试文件）→ 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Hugo → 发布。单文件模式文章 <code>.md</code> 会提交到 <code>存储目录/文件名.md</code>；页面目录模式提交到 <code>存储目录/目录名/index.md</code>。</li><li>点「查看文章」能打开站点文章页；单文件模式带图发布时图片会一并上传到仓库 <code>static/images</code>，页面目录模式图片写入文章目录。</li></ol><h2 id="图片存储路径" tabindex="-1">图片存储路径 <a class="header-anchor" href="#图片存储路径" aria-label="Permalink to &quot;图片存储路径&quot;">​</a></h2><p>图床选「当前平台」时，可以指定图片存到仓库哪里：</p><p><img src="'+o+`" alt="填写图片存储目录与访问链接" loading="lazy"></p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th></tr></thead><tbody><tr><td>图片存储目录</td><td><code>static/images</code></td></tr><tr><td>图片访问链接</td><td><code>images</code></td></tr></tbody></table><p>Hugo 的图片放在 <code>static</code> 下，构建后会原样复制到站点根目录。一般不需要改，改了请保证两个值<strong>对应</strong>。</p><p>2.4.0 起，「YAML 预设配置」支持日期、标题、别名、标签与分类占位符；2.5.0 起支持 <code>[attr:属性名]</code> 文档属性占位符。预设仅在首次生成平台 YAML 时应用，已发布文章的更新沿用已保存的 YAML。完整语法与修改已有文章的方法见 <a href="/siyuan-plugin-publisher/guide/single-publish.html#yaml-预设配置">YAML 预设配置</a>。</p><h2 id="六、yaml-预设与思源文档属性" tabindex="-1">六、YAML 预设与思源文档属性 <a class="header-anchor" href="#六、yaml-预设与思源文档属性" aria-label="Permalink to &quot;六、YAML 预设与思源文档属性&quot;">​</a></h2><p>2.5.0 起，「YAML 预设配置」可以用 <code>[attr:属性名]</code> 读取思源文档属性，包括 <code>custom-*</code> 自定义属性。例如 Hugo 主题常用的封面与权重：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cover&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[attr:custom-cover]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;weight&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[attr:custom-weight|int]&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>在思源文档属性中保存 <code>custom-cover</code>、<code>custom-weight</code> 后，首次发布就会把值写入 Front Matter。属性不存在或为空时，整字段不写入（嵌在文本中时替换为空字符串）；需要数字/布尔时可用 <code>|int</code>、<code>|float</code>、<code>|bool</code> 后缀，转换失败保留原字符串。预设只在首次生成平台 YAML 时应用，已有文章请在「详细发布 → 源码模式」修改 YAML 后保存再更新。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认 Token 对目标仓库有 push 权限，仓库名与分支正确，存储目录已存在。权限不足会收到 401/403。</li><li><strong>图片要怎么发布</strong>：单文件模式选「当前平台」图床，图片上传到仓库 <code>static/images</code>，文章中引用绝对路径 <code>/images/&lt;图片名&gt;</code>；页面目录模式图片自动写入 <code>index.md</code> 同目录，正文使用相对文件名。</li><li><strong>怎么启用 Leaf Bundle</strong>：在「内容组织方式」选「页面目录（Leaf Bundle）」并保存即可；已有文章不会自动搬迁。图片需使用「当前平台」图床；PicGo 外链图片仍按外链保留。</li><li><strong>查看链接打不开</strong>：开启「YAML 永久链接」时，单文件模式 front matter 的 <code>url</code> 固定为 <code>/post/&lt;slug&gt;.html</code>，页面目录模式为按存储目录推导的目录式地址；确认「文章预览规则」与站点实际地址一致。另外请确认博客使用的主题/发布脚本会对仓库变更执行 <code>hugo</code> 构建（如 GitHub Actions），否则新文章不会出现在线上站点。</li><li><strong>发布后线上没有新文章</strong>：Hugo 是通过构建（<code>hugo</code>/<code>hugo build</code>）从仓库内容生成站点的。确认仓库配置了自动构建（GitHub Actions / Vercel / Netlify 等）；仅推送 <code>.md</code> 不会直接改变已部署站点，需触发一次构建。</li><li><strong>更新与删除</strong>：点「更新」会重新提交并产生一次新提交；「删除」在单文件模式移除对应 <code>.md</code>，页面目录模式移除 <code>index.md</code> 并清理同目录图片；都需重新构建才能从站点移除。</li></ul>`,25)])])}const b=e(i,[["render",c]]);export{m as __pageData,b as default};
